do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: The New Heaven and the New Earth$j$, $j${"questions": [{"q": "What does Revelation 21:4 say God will wipe away?", "options": ["All tears from their eyes", "Every kingdom", "The old books", "Every temple"]}, {"q": "What does the One on the throne say in Revelation 21:5?", "options": ["Keep the old law", "I make all things new", "I will return tomorrow", "Build a house"]}, {"q": "What did John see flowing out of the throne of God in Revelation 22:1?", "options": ["A sea of glass", "A golden road", "A fire", "A pure river of water of life"]}, {"q": "According to Revelation 22:17, who may take the water of life freely?", "options": ["Only priests", "Only the first believers", "Only the wealthy", "Whosoever will"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: The New Heaven and the New Earth$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,3}'::int[], array[$j$God shall wipe away all tears from their eyes, and there shall be no more death, sorrow, crying or pain.$j$,$j$He said, Behold, I make all things new.$j$,$j$John saw a pure river of water of life, clear as crystal.$j$,$j$Whosoever will, let him take the water of life freely.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: The New Heaven and the New Earth$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: The Book of Revelation$j$, $j${"questions": [{"q": "Who wrote the book of Revelation, and where was he when he received the vision?", "options": ["Paul, in a Roman prison", "James, in Antioch", "Peter, in Jerusalem", "John, on the isle of Patmos"]}, {"q": "What did Jesus say to Smyrna in Revelation 2:10?", "options": ["You are neither cold nor hot", "You have left your first love", "Be thou faithful unto death, and I will give thee a crown of life", "Leave the city"]}, {"q": "Who did John see in the midst of the throne in Revelation 5:6?", "options": ["A great eagle", "A mighty king", "An angel", "A Lamb as it had been slain"]}, {"q": "What name is written on Christ in Revelation 19:16?", "options": ["KING OF KINGS, AND LORD OF LORDS", "Prince of Peace", "High Priest of the temple", "Teacher of Israel"]}, {"q": "What does Revelation 21:4 promise?", "options": ["No more death, sorrow, crying or pain", "A new temple", "An earthly kingdom for a thousand years", "The return of the law"]}, {"q": "What is the final invitation in Revelation 22:17?", "options": ["Build a city", "Give an offering", "Wait until the end", "Whosoever will, let him take the water of life freely"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Book of Revelation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,0,0,3}'::int[], array[$j$John received the vision on the isle called Patmos.$j$,$j$Jesus encouraged the suffering church to stay faithful, with the promise of a crown of life.$j$,$j$The Lamb is Jesus, who died for us and is worthy to open the book.$j$,$j$His name is KING OF KINGS, AND LORD OF LORDS.$j$,$j$God will wipe away all tears, and the former things are passed away.$j$,$j$The Bible ends with a free invitation to anyone who is thirsty.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Book of Revelation$j$ on conflict (item_id) do nothing;
end
$seed$;
